set -uo pipefail
export LC_ALL=C.UTF-8
BASE={{ execution_path }}
SRC={{ java_source_dir }}
python3 - "$BASE" "$SRC" <<'PYEOF' || echo 'NICHT GEMESSEN: java_files_scanned (measurement script failed)'
# Shared helpers for the Java audit fact sheets: comment/string stripping and brace matching.
# Regex-based on purpose (no parser dependency); every heuristic yields candidates, never verdicts.
import os
import re


def strip_java(src):
    """Blank out comments, string/char literals and text blocks, keeping offsets and newlines."""
    out = list(src)
    i, n = 0, len(src)

    def blank(a, b):
        for k in range(a, b):
            if out[k] != '\n':
                out[k] = ' '

    while i < n:
        c = src[i]
        if src.startswith('//', i):
            j = src.find('\n', i)
            j = n if j < 0 else j
            blank(i, j)
            i = j
        elif src.startswith('/*', i):
            j = src.find('*/', i + 2)
            j = n if j < 0 else j + 2
            blank(i, j)
            i = j
        elif src.startswith('"""', i):
            j = src.find('"""', i + 3)
            j = n if j < 0 else j + 3
            blank(i + 1, j - 1)
            i = j
        elif c == '"' or c == "'":
            j = i + 1
            while j < n and src[j] != c and src[j] != '\n':
                j += 2 if src[j] == '\\' else 1
            j = min(j + 1, n)
            blank(i + 1, j - 1)
            i = j
        else:
            i += 1
    return ''.join(out)


def match_brace(s, open_idx):
    """Index of the brace closing the one at open_idx, or len(s)."""
    depth = 0
    for k in range(open_idx, len(s)):
        ch = s[k]
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0:
                return k
    return len(s)


def match_paren(s, open_idx):
    depth = 0
    for k in range(open_idx, len(s)):
        ch = s[k]
        if ch == '(':
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0:
                return k
    return len(s)


def line_of(s, idx):
    return s.count('\n', 0, idx) + 1


MODIFIERS = r'(?:(?:public|protected|private|static|final|synchronized|abstract|native|default|strictfp)\s+)*'
METHOD_RE = re.compile(
    r'(?P<annos>(?:@\w+(?:\.\w+)*(?:\([^()]*(?:\([^()]*\)[^()]*)*\))?\s+)*)'
    r'(?P<mods>' + MODIFIERS + r')'
    r'(?:<[^<>]*(?:<[^<>]*>[^<>]*)*>\s+)?'
    r'(?P<ret>[\w.$]+(?:<[^;{}()]*?>)?(?:\[\])*)\s+'
    r'(?P<name>[a-zA-Z_$][\w$]*)\s*\((?P<params>[^;{}()]*(?:\([^()]*\)[^;{}()]*)*)\)\s*'
    r'(?:throws\s+[\w.$,\s]+)?\{')
CTOR_KEYWORDS = {'if', 'for', 'while', 'switch', 'catch', 'synchronized', 'return', 'new', 'else', 'try', 'do'}


def methods(stripped):
    """Method declarations with body span: dicts name/mods/annos/params/start/end/line."""
    found = []
    for m in METHOD_RE.finditer(stripped):
        name = m.group('name')
        if name in CTOR_KEYWORDS or m.group('ret') in CTOR_KEYWORDS:
            continue
        body_open = m.end() - 1
        found.append({
            'name': name,
            'mods': m.group('mods').split(),
            'annos': m.group('annos'),
            'params': m.group('params').strip(),
            'ret': m.group('ret'),
            'start': body_open,
            'end': match_brace(stripped, body_open),
            'line': line_of(stripped, m.start('name')),
        })
    return found


def java_files(root):
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if d not in ('build', 'node_modules') and not d.startswith(('.', 'target')))
        for f in sorted(filenames):
            if f.endswith('.java'):
                yield os.path.join(dirpath, f)


def java_version(base):
    """(version, source) from Maven or Gradle build files, or (None, reason)."""
    pats = [
        (r'<maven\.compiler\.release>\s*(\d+)', 'maven.compiler.release'),
        (r'<java\.version>\s*(\d+)', 'java.version'),
        (r'<release>\s*(\d+)\s*</release>', 'compiler release'),
        (r'<maven\.compiler\.source>\s*(?:1\.)?(\d+)', 'maven.compiler.source'),
        (r'JavaLanguageVersion\.of\(\s*(\d+)', 'gradle toolchain'),
        (r'sourceCompatibility\s*=\s*[\'"]?(?:JavaVersion\.VERSION_)?(?:1[._])?(\d+)', 'gradle sourceCompatibility'),
    ]
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames[:] = [d for d in dirnames if d not in ('build', 'node_modules') and not d.startswith(('.', 'target'))]
        if dirpath.count(os.sep) - base.count(os.sep) > 2:
            dirnames[:] = []
        for f in ('pom.xml', 'build.gradle', 'build.gradle.kts'):
            if f in filenames:
                try:
                    text = open(os.path.join(dirpath, f), encoding='utf-8', errors='replace').read()
                except OSError:
                    continue
                for pat, label in pats:
                    m = re.search(pat, text)
                    if m:
                        return int(m.group(1)), os.path.relpath(os.path.join(dirpath, f), base) + ' ' + label
    return None, 'no pom.xml/build.gradle with a Java version found'


class Sheet:
    """Collects TREFFER lines per kind with a cap, then prints FAKT counts and the hits."""

    def __init__(self, cap):
        self.cap = cap
        self.hits = {}

    def hit(self, kind, text):
        self.hits.setdefault(kind, []).append(text)

    def count(self, kind):
        return len(self.hits.get(kind, []))

    def emit(self, kinds):
        for kind in kinds:
            rows = self.hits.get(kind, [])
            print('FAKT %s_count: %d' % (kind, len(rows)))
        print('')
        for kind in kinds:
            rows = self.hits.get(kind, [])
            for r in rows[:self.cap]:
                print('TREFFER %s: %s' % (kind, r))
            if len(rows) > self.cap:
                print('# %d more %s hits not listed' % (len(rows) - self.cap, kind))


# Fact sheet for the Java persistence/transaction audit. Usage: persistence_facts.py <repo-root> <source-dir>
import os
import re
import sys


SLOW = [
    ('http', r'\bHttpClient\b|\.send(?:Async)?\s*\(|\bRestTemplate\b|\bRestClient\b|\bWebClient\b|\bopenConnection\s*\(|\b\w*[Hh]ttp\w*[Cc]lient\.\w+\s*\('),
    ('process', r'\bProcessBuilder\b|\bRuntime\.getRuntime\(\)\.exec\s*\(|\.waitFor\s*\('),
    ('docker', r'\b\w+Cmd\s*\(|\bDockerClient\b|\bdocker\w*\.\w+\s*\('),
    ('sleep', r'\bThread\.sleep\s*\(|\bTimeUnit\.\w+\.sleep\s*\('),
    ('ai/cli', r'\b\w*(?:[Cc]laude|[Cc]odex|[Pp]i|[Aa]i|[Ll]lm|[Cc]li)\w*(?:Service|Provider|Client|Runner)\.(?:execute|run|call|complete|reason|chat|ask)\w*\s*\('),
    ('mail/messaging', r'\b\w*(?:[Mm]ail[Ss]ender|[Kk]afka[Tt]emplate|[Rr]abbit[Tt]emplate|[Jj]ms[Tt]emplate)\.\w+\s*\('),
    ('future-wait', r'\b\w*[Ff]uture\w*\.(?:get|join)\s*\(|\.await\s*\('),
]
SLOW_RE = [(label, re.compile(p)) for label, p in SLOW]
CALL_RE = re.compile(r'(?<![\w.$])(?:this\.)?([a-z_$][\w$]*)\s*\(')
READ_VERBS = r'(?:find|get|count|exists|query|read|load|search|stream|list)'
REPO_READ = re.compile(r'\b(\w*[Rr]epository)\.(%s\w*)\s*\(' % READ_VERBS)
LOOP_RE = re.compile(r'\b(for|while)\s*\(|\.forEach\s*\(')
TX_ANNO = re.compile(r'@(?:[\w$]+\.)*Transactional\b(?!EventListener)(\s*\([^)]*\))?')


def slow_in(text):
    for label, rx in SLOW_RE:
        m = rx.search(text)
        if m:
            return label, m.start()
    return None


def expand(s, by_name, body, own_pos, depth, chain=()):
    for c in CALL_RE.finditer(body):
        for target in by_name.get(c.group(1), []):
            if target['start'] <= own_pos <= target['end'] or target['name'] in chain:
                continue
            tbody = s[target['start']:target['end']]
            hit = slow_in(tbody)
            path = chain + (target['name'],)
            if hit:
                return hit[0], target['start'] + hit[1], ' via ' + ' -> '.join('%s()' % n for n in path)
            if depth > 1:
                deeper = expand(s, by_name, tbody, target['start'], depth - 1, path)
                if deeper:
                    return deeper
    return None


def loop_bodies(s):
    for lm in LOOP_RE.finditer(s):
        p_close = match_paren(s, s.find('(', lm.start()))
        if lm.group(1) is None:
            yield lm.start(), lm.start(), p_close
            continue
        b_open = s.find('{', p_close)
        if b_open < 0 or s[p_close + 1:b_open].strip():
            stmt_end = s.find(';', p_close)
            yield lm.start(), p_close, stmt_end if stmt_end > 0 else p_close
        else:
            yield lm.start(), b_open, match_brace(s, b_open)


def config_files(base):
    for dirpath, dirnames, filenames in os.walk(base):
        dirnames[:] = [d for d in dirnames if not d.startswith(('.', 'target')) and d not in ('build', 'node_modules', 'test')]
        for f in filenames:
            if re.match(r'application.*\.(ya?ml|properties)$', f):
                yield os.path.join(dirpath, f)


def main():
    base = os.path.abspath(sys.argv[1])
    src_root = os.path.join(base, sys.argv[2])
    sheet = Sheet(cap=40)
    files = entities = entities_versioned = tx_methods = 0

    print('## FAKTENBLATT')
    print('# Measured deterministically (regex over the source, comments and strings removed).')
    print('# TREFFER lines are candidates with a location, not proof; check each one in the source.')
    print('')
    if not os.path.isdir(src_root):
        print('NICHT GEMESSEN: java_files_scanned (source directory %s not found)' % sys.argv[2])
        return

    osiv, osiv_src = None, None
    pool, pool_src = None, None
    for p in config_files(base):
        text = open(p, encoding='utf-8', errors='replace').read()
        m = re.search(r'open-in-view\s*[:=]\s*(true|false)', text)
        if m and osiv is None:
            osiv, osiv_src = m.group(1), os.path.relpath(p, base)
        m = re.search(r'maximum-pool-size\s*[:=]\s*(\d+)', text)
        if m and pool is None:
            pool, pool_src = m.group(1), os.path.relpath(p, base)
    print('FAKT open_in_view: %s' % ('%s (%s)' % (osiv, osiv_src) if osiv else 'not set (Spring default true, with a warning at startup)'))
    if pool:
        print('FAKT connection_pool_max: %s (%s)' % (pool, pool_src))
    else:
        print('NICHT GEMESSEN: connection_pool_max (no maximum-pool-size in application*.yml/properties)')

    for path in java_files(src_root):
        rel = os.path.relpath(path, base)
        try:
            raw = open(path, encoding='utf-8', errors='replace').read()
        except OSError:
            continue
        files += 1
        s = strip_java(raw)
        meths = methods(s)
        by_name = {}
        for m in meths:
            by_name.setdefault(m['name'], []).append(m)

        # class-level @Transactional applies to all public methods of the class
        class_m = re.search(r'((?:@[\w.]+(?:\([^()]*\))?\s+)*)(?:public\s+|abstract\s+|final\s+)*class\s+\w+', s)
        class_tx = bool(class_m and TX_ANNO.search(class_m.group(1)))
        readonly_class = bool(class_m and re.search(r'readOnly\s*=\s*true', class_m.group(1) or ''))

        tx_names = set()
        for m in meths:
            own = TX_ANNO.search(m['annos'])
            is_tx = bool(own) or (class_tx and 'public' in m['mods'])
            if not is_tx:
                continue
            tx_methods += 1
            tx_names.add(m['name'])
            if own and ('private' in m['mods'] or 'final' in m['mods'] or 'static' in m['mods']):
                sheet.hit('transactional_ineffective', '%s:%d @Transactional on %s method %s() has no effect (proxy)' % (
                    rel, m['line'], next(x for x in ('private', 'final', 'static') if x in m['mods']), m['name']))
            body = s[m['start']:m['end']]
            hit = slow_in(body)
            via = ''
            if hit:
                pos = m['start'] + hit[1]
            else:
                deep = expand(s, by_name, body, m['start'], 2)
                if deep:
                    hit, pos, via = (deep[0], deep[1]), deep[1], deep[2]
            if hit:
                sheet.hit('transactional_slow_call', '%s:%d %s() keeps the transaction open -> %s in line %d%s' % (
                    rel, m['line'], m['name'], hit[0], line_of(s, pos), via))

        # TransactionTemplate callbacks with slow calls
        for tm in re.finditer(r'\b\w*[tT]ransactionTemplate\.(execute|executeWithoutResult)\s*\(', s):
            p_close = match_paren(s, tm.end() - 1)
            hit = slow_in(s[tm.end():p_close])
            if hit:
                sheet.hit('transactional_slow_call', '%s:%d TransactionTemplate.%s callback -> %s in line %d' % (
                    rel, line_of(s, tm.start()), tm.group(1), hit[0], line_of(s, tm.end() + hit[1])))

        # @Transactional methods called from the same class bypass the proxy
        for name in tx_names:
            for c in re.finditer(r'(?<![\w.$])(?:this\.)?%s\s*\(' % re.escape(name), s):
                enclosing = [mm for mm in meths if mm['start'] <= c.start() <= mm['end']]
                if not enclosing or enclosing[-1]['name'] == name:
                    continue
                caller = enclosing[-1]
                if caller['name'] in tx_names:
                    continue
                sheet.hit('transactional_self_call', '%s:%d %s() calls @Transactional %s() in the same class (no proxy, no transaction)' % (
                    rel, line_of(s, c.start()), caller['name'], name))

        # repository reads inside loops (N+1 candidates)
        seen = set()
        for start, b_open, b_end in loop_bodies(s):
            for rm in REPO_READ.finditer(s, b_open, b_end):
                ln = line_of(s, rm.start())
                if (rel, ln) in seen:
                    continue
                seen.add((rel, ln))
                sheet.hit('repository_in_loop', '%s:%d %s.%s in a loop starting at line %d' % (
                    rel, ln, rm.group(1), rm.group(2), line_of(s, start)))

        # findAll() without paging loads the whole table
        for fm in re.finditer(r'\b(\w*[Rr]epository)\.findAll\s*\(\s*\)', s):
            sheet.hit('find_all_unbounded', '%s:%d %s.findAll() without Pageable/limit' % (rel, line_of(s, fm.start()), fm.group(1)))

        # query strings built by concatenation (injection and plan-cache risk)
        for qm in re.finditer(r'\b(createQuery|createNativeQuery|queryForList|queryForObject|query|update|execute)\s*\(', s):
            if qm.group(1) in ('query', 'update', 'execute') and not re.search(r'[jJ]dbc\w*\s*\.\s*$', s[max(0, qm.start() - 40):qm.start()]):
                continue
            args = s[qm.end():match_paren(s, qm.end() - 1)]
            first = args.split(',')[0]
            if re.search(r'"\s*\+|\+\s*"|\.formatted\s*\(|String\.format\s*\(', first):
                sheet.hit('query_string_concat', '%s:%d %s with a concatenated SQL/JPQL string' % (rel, line_of(s, qm.start()), qm.group(1)))

        # @Modifying repository methods without a transaction
        for mm in meths:
            if '@Modifying' in mm['annos'] and not TX_ANNO.search(mm['annos']) and not class_tx:
                sheet.hit('modifying_without_tx', '%s:%d @Modifying %s() without @Transactional' % (rel, mm['line'], mm['name']))
        for am in re.finditer(r'@Modifying\b(?:\s*\([^)]*\))?\s*(?:@[\w.]+(?:\s*\((?:[^()]|\([^()]*\))*\))?\s*)*'
                              r'(?:public\s+|default\s+)?[\w<>\[\],.?\s]+?\s+(\w+)\s*\([^;{]*\)\s*;', s):
            window = s[max(0, am.start() - 200):am.end()]
            if not TX_ANNO.search(window) and not class_tx:
                sheet.hit('modifying_without_tx', '%s:%d @Modifying %s() without @Transactional' % (rel, line_of(s, am.start()), am.group(1)))

        # entities
        if re.search(r'@Entity\b', s):
            entities += 1
            if re.search(r'@Version\b', s):
                entities_versioned += 1
            for lm in re.finditer(r'@(Data|EqualsAndHashCode|ToString)\b(\s*\([^)]*\))?', s):
                if lm.group(1) == 'ToString' and re.search(r'exclude|onlyExplicitlyIncluded', lm.group(2) or ''):
                    continue
                if lm.group(1) == 'EqualsAndHashCode' and re.search(r'onlyExplicitlyIncluded', lm.group(2) or ''):
                    continue
                sheet.hit('entity_lombok', '%s:%d @%s on an entity (equals/hashCode/toString over relations and lazy fields)' % (
                    rel, line_of(s, lm.start()), lm.group(1)))
            for em in re.finditer(r'FetchType\.EAGER', s):
                sheet.hit('eager_fetch', '%s:%d FetchType.EAGER' % (rel, line_of(s, em.start())))
            for cm in re.finditer(r'@(ManyToOne|ManyToMany)\s*\(([^)]*cascade[^)]*(ALL|REMOVE)[^)]*)\)', s):
                sheet.hit('cascade_remove_to_parent', '%s:%d @%s with cascade %s' % (rel, line_of(s, cm.start()), cm.group(1), cm.group(3)))

    print('FAKT java_files_scanned: %d' % files)
    print('FAKT entities: %d' % entities)
    print('FAKT entities_with_version: %d' % entities_versioned)
    print('FAKT transactional_methods: %d' % tx_methods)
    kinds = ['transactional_slow_call', 'transactional_self_call', 'transactional_ineffective', 'repository_in_loop',
             'find_all_unbounded', 'query_string_concat', 'modifying_without_tx', 'entity_lombok', 'eager_fetch',
             'cascade_remove_to_parent']
    sheet.emit(kinds)
    print('')
    print('## PFLICHTFELDER')
    print('PFLICHT-FAKTEN: java_files_scanned transactional_methods transactional_slow_call_count repository_in_loop_count')


if __name__ == '__main__':
    main()
PYEOF
